package android.app;import android.content.*;import android.os.Bundle;import android.view.*;public class Activity extends Context{private Intent intent;public boolean finishing,destroyed;public final Window window=new Window();public Object content;public int transitions;public void setIntent(Intent value){intent=value;}public Intent getIntent(){return intent;}public void onCreate(Bundle state){}protected void onResume(){}protected void onPause(){}protected void onDestroy(){destroyed=true;}protected void onNewIntent(Intent intent){setIntent(intent);}public void finish(){finishing=true;}public boolean isFinishing(){return finishing;}public boolean isDestroyed(){return destroyed;}public void setContentView(View view){content=view;}public Window getWindow(){return window;}public void overridePendingTransition(int enter,int exit){if(enter!=0||exit!=0)throw new AssertionError();transitions++;}}
